/* Contenuti delle lezioni — italiano */
I18N.registerLessons("it", {

/* ===================== PIANOFORTE ===================== */
"piano-1":{title:"Incontro con i tasti",goal:"Individuare qualsiasi nota del pianoforte in cinque secondi",b:{
0:"Il pianoforte spaventa: 88 tasti. La verità? Esistono soltanto <b>12 tasti</b> che si ripetono all'infinito. Appena vedi lo schema, l'intero strumento si apre.",
1:"Il segreto sta nei tasti neri: sono raggruppati a <b>due</b> e a <b>tre</b>, alternati. Questa è la tua mappa.",
2:["Trova un gruppo di due tasti neri.","Il tasto bianco subito alla loro sinistra (verso i gravi) è il <b>do (C)</b>.","Da lì basta proseguire: do, re, mi, fa, sol, la, si — e di nuovo do.","Ogni do successivo è lo stesso suono, solo più acuto. Si chiama <b>ottava</b>."],
3:"Premi il tasto evidenziato: è il do (C4). Prova a trovare anche gli altri do.",
4:"<b>Consiglio d'oro:</b> il do centrale (C4) si trova più o meno al centro del pianoforte, di fronte alla serratura o al logo. È il punto di riferimento di ogni pianista.",
5:"La scala di do maggiore — le sette note bianche e ritorno al do",
6:{q:"Come si individua la nota do sul pianoforte?",o:["Il tasto bianco a sinistra di tre neri","Il tasto bianco attaccato al gruppo di due neri, dal lato grave","Il primo tasto nero","Il tasto bianco al centro della tastiera"],w:"Il do è sempre il tasto bianco attaccato al gruppo di due neri, dal lato dei suoni gravi."},
7:"Siediti alla tastiera (vera o a schermo) e di' ad alta voce tutti i do, poi tutti i fa. Tre minuti e hai finito."}},

"piano-2":{title:"La mano destra — cinque dita, cinque note",goal:"Suonare do–re–mi–fa–sol di seguito senza guardare le mani",b:{
0:"Al pianoforte ogni dito ha un numero: <b>1 = pollice</b>, 2 = indice, 3 = medio, 4 = anulare, 5 = mignolo. La numerazione è identica per entrambe le mani.",
1:"Appoggia il pollice destro sul <b>do (C4)</b> e ogni dito successivo sul tasto bianco seguente. Ora le tue cinque dita stanno esattamente su do-re-mi-fa-sol. È la «posizione di do», la prima posizione che ogni pianista impara.",
2:"Posizione di do — dita 1, 2, 3, 4, 5",
3:["Curva leggermente le dita, come se tenessi una piccola arancia.","Tieni il polso dritto: né affossato né sollevato.","Suona 1-2-3-4-5 lentamente, ogni nota con lo stesso volume.","Ora torna indietro: 5-4-3-2-1.","Quando scorre, chiudi gli occhi e suona di nuovo."],
4:"<b>L'uniformità del suono conta più della velocità.</b> Il dito debole (il 4) cercherà sempre di suonare più piano. Dedicagli attenzione particolare.",
5:"Esercizio per le dita n. 1",
6:{q:"Quale dito è il numero 1 al pianoforte?",o:["Il mignolo","Il medio","Il pollice","L'indice"],w:"Il pollice è sempre il dito numero 1, in entrambe le mani."},
7:"Suona l'esercizio cinque volte di fila senza errori. Se sbagli, ricomincia più lentamente."}},

"piano-3":{title:"Il tuo primo brano",goal:"Suonare una melodia completa a orecchio e leggendo",b:{
0:"È arrivato il momento: stai suonando un brano. «Brilla, brilla, stellina» è una melodia popolare francese del Settecento (pubblico dominio) — Mozart ci scrisse persino delle variazioni.",
1:"Tutte le note stanno nella posizione di do che hai imparato, tranne il <b>la (A4)</b>, che raggiungiamo spostando leggermente il mignolo.",
2:"Brilla, brilla, stellina — la melodia completa",
3:"Le note che servono per il brano",
4:["Ascolta la melodia due volte con il pulsante di riproduzione.","Suona solo le prime quattro note: do do sol sol.","Aggiungi: la la sol (il sol è lungo, due movimenti).","Prosegui: fa fa mi mi re re do.","Unisci tutto lentamente e solo dopo aggiungi velocità."],
5:"<b>La regola chiave dello studio da autodidatta:</b> lento = veloce. Un cervello che impara lentamente e senza errori arriva alla velocità tre volte prima.",
6:{q:"A che tempo si deve iniziare un brano nuovo?",o:["Il più velocemente possibile","Al tempo in cui lo suoni senza errori","Al tempo originale del brano","Non ha importanza"],w:"Il tempo giusto è quello in cui riesce senza errori. La velocità arriva da sola dopo."},
7:"Suona il brano tre volte di fila senza fermarti."}},

"piano-4":{title:"Il ritmo — la lingua del tempo",goal:"Contare 1-2-3-4 e suonare figure diverse",b:{
0:"La musica non è solo quali note, ma <b>quando</b>. Le figure di base:",
1:["<b>Semibreve</b> — dura 4 movimenti.","<b>Minima</b> — 2 movimenti.","<b>Semiminima</b> — un movimento. È la figura più comune di tutte.","<b>Croma</b> — mezzo movimento. Si conta 1-e-2-e."],
2:"Esercizio di ritmo — contare a quattro",
3:"La maggior parte dei brani popolari ha <b>quattro movimenti per battuta</b> (4/4). Il primo movimento è più forte: è il polso del brano.",
4:"Prima si batte le mani, poi si suona. Se non riesci a battere un ritmo, non riuscirai neanche a suonarlo.",
5:"La stessa nota, figure diverse",
6:{q:"Quanti movimenti dura una semiminima in 4/4?",o:["4","2","1","Mezzo"],w:"Una semiminima = un movimento. Quattro semiminime riempiono una battuta completa."},
7:"Metti il metronomo a 70 e batti le mani esattamente sui movimenti. Poi batti le crome (due volte per movimento)."}},

"piano-5":{title:"Entra la mano sinistra",goal:"Suonare un basso semplice con la mano sinistra",b:{
0:"La mano sinistra suona i suoni gravi: la base armonica. Iniziamo semplice: una nota per battuta.",
1:"Do e sol nell'ottava della mano sinistra",
2:["Appoggia il mignolo sinistro sul do (C3).","Appoggia il pollice sul sol (G3).","Suona do e conta 4. Suona sol e conta 4.","Quando è stabile, suona do-sol-do-sol sui movimenti 1 e 3."],
3:"La mano sinistra all'inizio sembra sempre «stupida». È del tutto normale: ha semplicemente avuto meno allenamento nella vita. In una settimana recupera.",
4:"Esercizio di basso",
5:{q:"Qual è il ruolo principale della mano sinistra nel pianoforte popolare?",o:["Suonare la melodia","Suonare il basso e l'armonia","Girare le pagine","Solo tenere il tempo"],w:"La mano sinistra costruisce la base armonica su cui poggia la melodia della destra."},
6:"Suona l'esercizio di basso con il metronomo a 70."}},

"piano-6":{title:"Le due mani insieme — il grande momento",goal:"Coordinare le mani in un esercizio semplice",b:{
0:"È qui che la maggior parte degli autodidatti si blocca, per un solo motivo: uniscono le mani troppo presto.",
1:["Suona la mano destra da sola finché non diventa completamente automatica.","Fai lo stesso con la sinistra.","Suona una sola battuta a due mani — e fermati.","Aggiungi una battuta alla volta.","Se ti blocchi, torna alle mani separate. Sempre."],
2:"Esercizio a due mani (la melodia)",
3:"Esercizio a due mani (il basso)",
4:"<b>Un trucco che funziona:</b> di' ad alta voce le note della mano destra mentre suoni. Costringe il cervello a separare le mani.",
5:{q:"Cosa fare quando non si riesce a unire le due mani?",o:["Suonare più veloce","Rinunciare alla mano sinistra","Tornare alle mani separate e unire una sola battuta","Passare a un altro brano"],w:"Dividere in pezzetti e ricostruire gradualmente è l'unico metodo che funziona."},
6:"Suona i due esercizi insieme, solo due battute, dieci volte."}},

"piano-7":{title:"Scala di do maggiore e il passaggio del pollice",goal:"Suonare un'ottava completa con una mano",b:{
0:"Hai solo cinque dita — e la scala ha otto note. La soluzione è il <b>passaggio del pollice</b>, il movimento più importante della tecnica pianistica.",
1:"Scala di do maggiore ascendente",
2:["Mano destra: 1-2-3 su do-re-mi.","Mentre il dito 3 suona il mi, il pollice «passa» sotto il palmo.","Il pollice atterra sul fa — e da lì 1-2-3-4-5 fino al do successivo.","La diteggiatura completa: 1 2 3 1 2 3 4 5.","In discesa: 5 4 3 2 1 3 2 1."],
3:"Il gomito e l'avambraccio devono accompagnare leggermente la mano verso destra. Se si muove solo il pollice, risulterà goffo.",
4:"Scala di do maggiore — andata e ritorno",
5:{q:"Quando il pollice passa sotto il palmo nella scala di do maggiore ascendente?",o:["Dopo la nota re","Mentre il dito 3 suona il mi","Dopo il sol","Non passa"],w:"Il passaggio avviene mentre il dito 3 suona il mi, perché il pollice arrivi in tempo sul fa."},
6:"Suona la scala andata e ritorno quattro volte con il metronomo a 60."}},

"piano-8":{title:"Gli accordi — tre note che cambiano tutto",goal:"Suonare C, F e G con la mano sinistra",b:{
0:"Un <b>accordo</b> è composto da tre o più note che suonano insieme. Un accordo maggiore si costruisce saltando: nota, salti una, nota, salti una, nota.",
1:"Accordo di do maggiore (C) — do-mi-sol",
2:"Accordo di fa maggiore (F) — fa-la-do",
3:"Accordo di sol maggiore (G) — sol-si-re",
4:"Questi tre accordi (C, F, G) bastano per centinaia di brani. Sono «i tre grandi» della tonalità.",
5:"Nota che tutti e tre si costruiscono allo stesso modo: dita 5-3-1 della mano sinistra, su un tasto bianco, salti, tasto, salti, tasto.",
6:{q:"Da quali note è formato l'accordo di do maggiore?",o:["do-re-mi","do-mi-sol","do-fa-la","do-sol-do"],w:"Un accordo maggiore si costruisce sul 1º, 3º e 5º grado della scala: do-mi-sol."},
7:"Alterna tra C, F e G, quattro movimenti per accordo, metronomo a 60."}},

"piano-9":{title:"L'accompagnamento — suonare un brano con gli accordi",goal:"Combinare melodia a destra e accordi a sinistra",b:{
0:"Ora uniamo: la mano sinistra suona un accordo, la destra la melodia. È così che si accompagna qualsiasi brano al mondo.",
1:["Suona «Brilla, brilla, stellina» con la mano destra.","Nella prima battuta — accordo C alla mano sinistra.","Quando la melodia arriva a «la la sol» — passa a F e poi a C.","Nella penultima battuta — G, e per finire di nuovo C."],
2:"Melodia su cui esercitarsi",
3:"<b>Come si capisce quale accordo va bene?</b> Guarda quale accordo contiene la nota che la melodia suona su quel movimento. Se la melodia suona mi, andrà bene C (do-mi-sol).",
4:{q:"Quale accordo contiene la nota la?",o:["C (do-mi-sol)","G (sol-si-re)","F (fa-la-do)","Nessuno"],w:"L'accordo F è formato da fa-la-do, quindi contiene la nota la."},
5:"Suona il brano con l'accompagnamento, molto lentamente, due volte."}},

"piano-10":{title:"Maggiore e minore — il colore emotivo",goal:"Riconoscere e suonare accordi minori",b:{
0:"La differenza tra «allegro» e «triste» in musica è <b>un semitono</b>. Sposta la nota centrale di un accordo maggiore di un tasto a sinistra e avrai un accordo minore.",
1:"Accordo di la minore (Am) — la-do-mi",
2:"Accordo di re minore (Dm) — re-fa-la",
3:"Accordo di mi minore (Em) — mi-sol-si",
4:"Suona C e poi Am uno dopo l'altro. Nota come cambia all'istante l'umore del suono. Questa è la forza dell'armonia.",
5:{q:"Qual è la differenza tra un accordo maggiore e uno minore?",o:["Il minore è più acuto","La nota centrale del minore è più bassa di un semitono","Il minore ha quattro note","Non c'è una vera differenza"],w:"La nota centrale (la terza) scende di un semitono: in questo sta tutta la differenza tra «allegro» e «triste»."},
6:"Suona la successione C – Am – F – G, quattro movimenti per accordo. È la successione più diffusa della musica popolare."}},

"piano-11":{title:"Dinamica, pedale ed espressione",goal:"Trasformare un'esecuzione tecnica in una musicale",b:{
0:"Due persone suoneranno le stesse note — e una sembrerà un robot. La differenza è la <b>dinamica</b>: la variazione del volume.",
1:["<b>Piano (p)</b> — debole. <b>Forte (f)</b> — forte.","<b>Crescendo</b> — aumento graduale. <b>Diminuendo</b> — calo graduale.","Suona la scala: parti piano, arriva al culmine sul do acuto e attenua in discesa.","Una frase musicale è come una frase parlata: ha un inizio, un culmine e una fine."],
2:"<b>Il pedale destro</b> (di risonanza) solleva gli smorzatori dalle corde e il suono continua a risuonare. La regola: cambiare pedale a ogni cambio di accordo, altrimenti si crea «fango».",
3:"La tecnica corretta: il pedale si preme <b>subito dopo</b> che il dito ha suonato, non prima. Si chiama «pedale ritardato».",
4:{q:"Quando si cambia il pedale?",o:["A ogni nota","A ogni cambio di accordo","Solo alla fine del brano","Mai, si tiene premuto"],w:"Cambiare pedale a ogni cambio di accordo mantiene il suono pulito."},
5:"Suona la scala con crescendo in salita e diminuendo in discesa."}},

"piano-12":{title:"Brano finale — Inno alla gioia",goal:"Suonare un'opera classica completa",b:{
0:"Hai finito il percorso di base. È ora di suonare un'opera vera: il tema della Nona sinfonia di Beethoven (1824), di pubblico dominio.",
1:"Inno alla gioia",
2:["Suona la mano destra da sola, quattro battute alla volta.","Aggiungi un basso semplice a sinistra: C – C – G – C.","Aggiungi la dinamica: inizio quieto, culmine al centro.","Aggiungi il pedale ai cambi di accordo.","Suona dall'inizio alla fine senza fermarti — anche se sbagli."],
3:"<b>La regola dell'esecutore esperto:</b> nell'esecuzione non ci si ferma a correggere. Si va avanti. Le correzioni appartengono allo studio, non all'esecuzione.",
4:{q:"Qual è il modo più efficace di studiare un brano nuovo?",o:["Suonarlo per intero all'infinito","Isolare i passaggi difficili e lavorare solo su quelli","Suonare solo le parti facili","Limitarsi ad ascoltare registrazioni"],w:"Il lavoro mirato sui passaggi difficili fa risparmiare ore. L'80 % del tempo va al 20 % più difficile."},
5:"Registrati mentre suoni (con il telefono) e riascoltati. Sentirai cose che non avevi notato suonando."}},

/* ===================== CHITARRA ===================== */
"guitar-1":{title:"Incontro con la chitarra e la postura corretta",goal:"Sedersi bene, tenerla bene e accordarla",b:{
0:"La chitarra ha sei corde. La più grossa (in alto) è il <b>mi basso (E)</b>, la più sottile (in basso) il <b>mi acuto (E)</b>. La numerazione va <b>dalla sottile alla grossa</b>: la più sottile è la corda 1.",
1:["Corda 6 — mi basso (E2)","Corda 5 — la (A2)","Corda 4 — re (D3)","Corda 3 — sol (G3)","Corda 2 — si (B3)","Corda 1 — mi acuto (E4)"],
2:"Il suono delle corde a vuoto — dalla grossa alla sottile",
3:"<b>Sedersi correttamente:</b> schiena dritta, cassa della chitarra sulla gamba destra (per i destrimani), manico leggermente inclinato verso l'alto. Pollice della mano sinistra dietro il manico, senza spuntare sopra.",
4:"Il dolore ai polpastrelli nelle prime due settimane è normale: la pelle si indurisce. Il dolore al polso o alla spalla <b>non</b> è normale e indica una postura sbagliata. Fermati e correggi la posizione.",
5:"Accorda la chitarra prima di ogni sessione. Una chitarra scordata insegna al tuo orecchio altezze sbagliate. Usa l'<a href='#/tools/tuner'>accordatore dell'app</a>.",
6:{q:"Quale corda è la numero 1?",o:["La più grossa","La più sottile","Quella centrale","Dipende dalla chitarra"],w:"La corda 1 è la più sottile: il mi acuto."},
7:"Accorda la chitarra, poi pizzica ogni corda a vuoto dicendone il nome ad alta voce."}},

"guitar-2":{title:"La mano destra — la tua prima pennata",goal:"Produrre un suono pulito e uniforme sulle corde a vuoto",b:{
0:"La mano destra è responsabile del suono e del ritmo. Si può suonare con il plettro o con le dita: partiamo dal plettro.",
1:["Tieni il plettro tra pollice e indice, lasciandone fuori solo 3–5 mm.","Il movimento parte dal polso, non dal gomito.","Pennata verso il basso su tutte e sei le corde: un unico suono continuo.","Ora verso l'alto, dalla corda sottile alla grossa.","Esercitati: giù, giù, giù, giù — a tempo uniforme."],
2:"Pennate in semiminime — quattro movimenti",
3:"Se il suono «inciampa», probabilmente stringi troppo il plettro. Una presa rilassata dà un suono scorrevole.",
4:{q:"Da dove deve partire il movimento della pennata?",o:["Dalla spalla","Dal gomito","Dal polso","Solo dalle dita"],w:"Il movimento dal polso è rilassato, veloce e non provoca infortuni."},
5:"Suona corde a vuoto per 2 minuti di fila con il metronomo a 70. Occhio all'uniformità."}},

"guitar-3":{title:"Il primo accordo — Em",goal:"Fare un accordo pulito e suonarlo a tempo",b:{
0:"Em (mi minore) è l'accordo più facile del mondo: solo due dita, e si suonano tutte e sei le corde.",
1:null,
2:["Dito 2 sul tasto 2 della corda 5 (la).","Dito 3 sul tasto 2 della corda 4 (re).","Premi vicino al tastino, non sopra e non a metà.","Le dita stanno sulla punta, non coricate.","Pizzica corda per corda e verifica che ognuna suoni pulita."],
3:"Suono «morto» o che frigge? Quasi sempre la causa è un dito coricato che sfiora una corda vicina. Alza il palmo e curva di più le dita.",
4:"Il metodo di verifica degli insegnanti: pizzica ogni corda separatamente (un «arpeggio»). La corda che non suona ti dice esattamente quale dito correggere.",
5:{q:"Cosa fare quando una corda dell'accordo frigge?",o:["Premere più forte con tutte le dita","Controllare quale dito è coricato e sfiora una corda vicina","Riaccordare la chitarra","Cambiare le corde"],w:"Nel 90 % dei casi un dito vicino tocca la corda. La soluzione è curvare le dita, non la forza."},
6:"Tieni Em e suona 16 movimenti di fila. Rilascia, scuoti la mano e ripeti: cinque volte."}},

"guitar-4":{title:"Un secondo accordo e il primo cambio",goal:"Passare da Em ad Am senza fermarsi",b:{
0:"Am (la minore) è esattamente la stessa forma di Em, solo spostata di una corda, con un dito in più.",
1:null,
2:["Prendi la forma di Em e spostala di una corda verso le corde sottili.","Aggiungi il dito 1 sul tasto 1 della corda 2 (si).","Non suonare la corda 6.","Passa Em → Am → Em → Am, senza pennare: solo con la mano."],
3:"<b>Il segreto dei cambi:</b> esercita il passaggio <u>senza pennare</u>, 20 volte. Il cervello impara il movimento senza la pressione del suono. Poi aggiungi la pennata.",
4:"<b>Dito d'ancoraggio:</b> tra Em e Am due dita mantengono la stessa forma. Non sollevare tutta la mano: falla scivolare.",
5:{q:"Qual è il modo più efficace di esercitare un cambio di accordo?",o:["Suonare il brano veloce all'infinito","Esercitare il solo movimento della mano, senza pennare","Esercitare ogni accordo separatamente","Esercitarsi solo con metronomo veloce"],w:"Separare il movimento della mano dalla pennata permette al cervello di imparare il gesto in modo pulito e rapido."},
6:"60 cambi Em↔Am. Conta ad alta voce. Quattro minuti che cambiano tutto."}},

"guitar-5":{title:"Il ritmo di accompagnamento — giù e su",goal:"Suonare il ritmo di accompagnamento più diffuso al mondo",b:{
0:"Il ritmo più elementare: <b>giù, giù-su, su-giù-su</b>. Se in tutta la vita impari un solo ritmo, che sia questo.",
1:["Conta ad alta voce: 1 e 2 e 3 e 4 e.","La mano si muove su e giù di continuo, come un pendolo, senza fermarsi.","Sui movimenti in cui non si suona, la mano continua a muoversi in aria, semplicemente non tocca.","Lo schema: ↓ . ↓↑ . ↑↓↑ (1, 2-e, 3-e-4-e)."],
2:"Il ritmo di accompagnamento di base",
3:"La mano che non si ferma è il segreto. I principianti fermano la mano e perdono il ritmo. Lasciala sempre in movimento.",
4:{q:"Perché la mano destra deve continuare a muoversi anche quando non penna?",o:["Perché fa bella figura","Per mantenere la sensazione continua del ritmo","Per non affaticare la mano","Non è importante"],w:"Il movimento continuo è il tuo orologio interno. Fermarsi spezza il ritmo."},
5:"Suona Em con questo ritmo per un minuto intero senza fermarti, poi Am."}},

"guitar-6":{title:"L'accordo di C — e un cambio più impegnativo",goal:"Fare un C pulito e inserirlo in una successione",b:{
0:"C (do maggiore) richiede tre dita su tre tasti diversi. È l'accordo che separa chi persevera da chi molla.",
1:null,
2:["Dito 1 — tasto 1, corda 2.","Dito 2 — tasto 2, corda 4.","Dito 3 — tasto 3, corda 5.","Non suonare la corda 6.","Assicurati che le corde a vuoto 1 e 3 suonino libere."],
3:"Se la corda 1 (la sottile) non suona, è il tuo dito 1 che ci è coricato sopra. Ruota leggermente il polso in avanti.",
4:{q:"Quali corde non si suonano in un accordo di C aperto?",o:["La corda 1","La corda 6","Le corde 5 e 6","Si suonano tutte"],w:"Nell'accordo di C si parte dalla quinta corda. La sesta non fa parte dell'accordo."},
5:"Esercita C → Am → C → Am, quattro movimenti ciascuno."}},

"guitar-7":{title:"G e D — il tuo primo brano a tre accordi",goal:"Suonare un brano completo con G, C e D",b:{
0:"Con G, C e D si possono suonare migliaia di brani. È la «famiglia di sol»: i tre accordi centrali della tonalità di sol maggiore.",
1:null,2:null,
3:"<b>La struttura classica:</b> G – G – C – C – G – G – D – C – G. Quattro movimenti per accordo.",
4:"Ritmo di accompagnamento per il brano",
5:"Nota che passando da G a C il dito 3 può restare sullo stesso tasto: è un «dito d'ancoraggio» che dimezza il cambio.",
6:{q:"Cosa hanno in comune gli accordi G, C e D?",o:["Sono tutti minori","Sono i tre accordi centrali della scala di sol maggiore","Sono sullo stesso tasto","Usano le stesse dita"],w:"Sono i gradi I, IV e V della scala di sol maggiore: lo scheletro armonico della maggior parte dei brani."},
7:"Suona il ciclo G-C-G-D due volte senza fermarti, anche se i cambi sono lenti."}},

"guitar-8":{title:"Cambi rapidi e dita d'ancoraggio",goal:"Accorciare il tempo di passaggio fra gli accordi",b:{
0:"I cambi lenti sono il problema numero uno dei chitarristi principianti. La soluzione non è né forza né velocità, ma <b>efficienza</b>.",
1:["<b>Dito d'ancoraggio:</b> individua un dito che resta fermo tra due accordi e non sollevarlo.","<b>Movimento minimo:</b> solleva le dita di soli 2 mm dalle corde.","<b>Tempismo:</b> cambia accordo sull'ultimo movimento, non dopo.","<b>L'esercizio dell'orologio:</b> imposta un minuto e conta i cambi puliti. Batti il tuo record ogni giorno."],
2:"Annota il tuo record di cambi nel diario di studio dell'app. Un progresso misurabile è il motore più forte della costanza.",
3:{q:"Che cos'è un «dito d'ancoraggio»?",o:["Il pollice dietro il manico","Un dito che resta fermo passando tra due accordi","Il dito più forte","Un dito che preme due corde"],w:"Un dito d'ancoraggio accorcia il cambio e fa da riferimento per le altre dita."},
4:"Un minuto di cambi C↔G. Annota il numero. Torna domani e superalo."}},

"guitar-9":{title:"Ritmi — variare l'accompagnamento",goal:"Conoscere tre ritmi diversi",b:{
0:"Gli stessi accordi con un altro ritmo suonano come un brano completamente diverso. Ecco tre ritmi che coprono quasi ogni stile.",
1:"Ritmo 1 — ballata lenta",
2:"Ritmo 2 — pop standard",
3:"Ritmo 3 — accento in levare",
4:"<b>Il ritmo in levare</b> — pennata solo sulle «e» tra i movimenti — dà una sensazione elastica e si adatta a reggae, ska e molti stili folk.",
5:{q:"Cosa cambia suonando gli stessi accordi con un ritmo diverso?",o:["L'armonia","Il carattere e lo stile del brano","L'altezza dei suoni","Solo la velocità"],w:"È il ritmo a definire lo stile. Gli stessi quattro accordi possono suonare come ballata, rock o reggae."},
6:"Suona la stessa successione di accordi con tutti e tre i ritmi."}},

"guitar-10":{title:"Il tuo primo assolo — la scala pentatonica",goal:"Improvvisare un assolo breve su cinque note",b:{
0:"La scala pentatonica (cinque note) è il segreto di ogni solista rock e blues. La sua magia: è quasi impossibile suonarci una nota «sbagliata».",
1:"Pentatonica minore di la — ascendente",
2:["Metti il dito 1 sul tasto 5, corda 6 (la).","Lo schema: 5-8 sulle corde 6 e 5, 5-7 sulle corde 4 e 3, 5-8 sulle corde 2 e 1.","Suona lo schema in salita e in discesa finché le dita non lo memorizzano.","Ora dimentica l'ordine: suona le note a caso. Questa è improvvisazione."],
3:"Un buon assolo non è fatto di molte note, ma di note con <b>silenzi</b> in mezzo. Lascia spazio per respirare.",
4:{q:"Perché è facile improvvisare con la scala pentatonica?",o:["Contiene solo note acute","Contiene 5 note che si adattano tutte armonicamente","Si può suonare solo su una corda","Si suona lentamente"],w:"Dalla scala sono state tolte le note «che stridono», perciò qualsiasi loro combinazione suona bene."},
5:"Improvvisa 8 battute in pentatonica su un metronomo."}},

"guitar-11":{title:"Famiglie di accordi — A, E, Dm",goal:"Portare a otto il tuo bagaglio di accordi",b:{
0:null,1:null,2:null,
3:"Con gli otto accordi imparati (Em, Am, C, G, D, A, E, Dm) puoi suonare la stragrande maggioranza dei brani popolari.",
4:"<b>La regola di compatibilità:</b> gli accordi della stessa «famiglia» (tonalità) suonano bene insieme. Famiglia di do: C, Dm, Em, F, G, Am. Famiglia di sol: G, Am, Bm, C, D, Em.",
5:{q:"Quale accordo non appartiene alla famiglia di sol maggiore?",o:["C","D","Em","F"],w:"F non fa parte della scala di sol maggiore (che ha il fa diesis). Appartiene alla famiglia di do."},
6:"Scegli quattro accordi della stessa famiglia e suonali in ciclo."}},

"guitar-12":{title:"Brano finale e uno sguardo avanti — il barré",goal:"Suonare un brano completo e conoscere la tappa successiva",b:{
0:"Hai finito il percorso di base. Sai accordare, pennare, suonare otto accordi, tre ritmi e un assolo.",
1:"Melodia di chiusura — Amazing Grace (pubblico dominio)",
2:"<b>La tappa successiva: l'accordo barré.</b> Il dito 1 si corica su tutte le corde e imita un capotasto mobile. Questo apre l'intero manico.",
3:["Appoggia il dito 1 disteso su tutte e sei le corde al tasto 1.","Usa il lato esterno del dito, non il polpastrello morbido.","Aggiungi la forma di E con le dita 2, 3 e 4 e otterrai un F.","Non scoraggiarti: un barré pulito richiede a molti dalle 2 alle 4 settimane."],
4:"Se senti dolore al polso mentre fai il barré, fermati. Il problema è l'angolo del pollice, non la mancanza di forza. Esercitati al tasto 5, dove le corde sono più morbide.",
5:{q:"Che cos'è un accordo barré?",o:["Un accordo suonato solo su corde a vuoto","Un accordo in cui un dito preme più corde insieme","Un accordo di quattro note","Un accordo veloce"],w:"Il dito 1 crea un «capotasto mobile» e permette di spostare le forme di accordo su tutto il manico."},
6:"Suona un brano completo della libreria con accompagnamento e registrati."}},

/* ===================== UKULELE ===================== */
"ukulele-1":{title:"Ukulele in 10 minuti",goal:"Suonare il primo accordo e pennarlo",b:{
0:"L'ukulele è lo strumento più rapido al mondo per iniziare: quattro corde di nylon morbide e accordatura standard <b>G-C-E-A</b>.",
1:"Le corde a vuoto",2:null,
3:["Tieni l'ukulele contro il corpo con l'avambraccio destro.","Metti il dito 3 sul tasto 3 della corda sottile (la).","Penna delicatamente verso il basso con il polpastrello dell'indice.","Ecco fatto: hai suonato un accordo di do."],
4:"Sull'ukulele si penna nel punto in cui il manico incontra la cassa: lì il suono è più pieno.",
5:{q:"Qual è l'accordatura standard di un ukulele soprano?",o:["E-A-D-G","G-C-E-A","C-F-A-D","D-G-B-E"],w:"G-C-E-A è l'accordatura standard, e il sol è in realtà più acuto del do («accordatura alta»)."},
6:"Penna l'accordo di C per un minuto a tempo uniforme."}},

"ukulele-2":{title:"Due accordi = un brano intero",goal:"Passare da C ad Am",b:{
0:null,
1:"Anche Am richiede un solo dito: il dito 2 sul tasto 2 della corda grossa (sol).",
2:"Ritmo semplice — quattro pennate in giù",
3:"Suona quattro movimenti di C, quattro di Am e ripeti. È già una forma di canzone legittima su cui cantare.",
4:{q:"Quante dita servono per l'accordo Am sull'ukulele?",o:["Una","Due","Tre","Quattro"],w:"Un solo dito, sul tasto 2 della corda grossa."},
5:"30 cambi C↔Am con metronomo lento."}},

"ukulele-3":{title:"Il terzo accordo — F",goal:"Suonare una successione di tre accordi",b:{
0:null,
1:"Con C, Am e F si possono già suonare centinaia di brani. La successione C – Am – F – C è un classico.",
2:"Ritmo pop",
3:{q:"Quale successione comune usa questi tre accordi?",o:["F – F – F – F","C – Am – F – C","C – C# – D","Solo Am"],w:"C – Am – F è una delle successioni più frequenti della musica popolare."},
4:"Suona la successione C-Am-F-C quattro volte di fila."}},

"ukulele-4":{title:"Ritmi e come variarli",goal:"Tre ritmi di accompagnamento",b:{
0:"Ritmo delle isole",1:"Valzer — tre movimenti",
2:"Il ritmo «delle isole» (giù, giù-su, su-giù-su) è il suono classico dell'ukulele.",
3:"Tieni la mano destra completamente rilassata. Sull'ukulele la forza produce un suono ruvido.",
4:{q:"Quanti movimenti ha una battuta di valzer?",o:["2","3","4","6"],w:"Il valzer è in 3/4: tre movimenti per battuta, con accento sul primo."},
5:"Suona la successione imparata con due ritmi diversi."}},

"ukulele-5":{title:"G ed Em — aprire il repertorio",goal:"Padroneggiare cinque accordi",b:{
0:null,1:null,
2:"G richiede tre dita a triangolo, mentre Em è una diagonale discendente. Entrambi vanno studiati lentamente all'inizio.",
3:"Esercita il cambio C→G senza pennare, 20 volte. Noterai che la mano «impara» la forma in pochi minuti.",
4:{q:"Cosa aiuta di più a padroneggiare un nuovo cambio di accordo?",o:["Suonare veloce","Esercitare il movimento senza pennare","Premere più forte","Cambiare le corde"],w:"Separare il movimento dal suono accelera l'apprendimento motorio."},
5:"30 cambi C↔G e 30 cambi Am↔Em."}},

"ukulele-6":{title:"Fingerpicking",goal:"Suonare un arpeggio di base",b:{
0:"Invece di pennare tutte le corde insieme, le pizzicheremo una dopo l'altra: si chiama <b>arpeggio</b> e si adatta ai brani calmi.",
1:["Pollice — corda 4 (sol).","Indice — corda 3 (do).","Medio — corda 2 (mi).","Anulare — corda 1 (la).","Suona 4-3-2-1 e poi 1-2-3-4."],
2:"Arpeggio sull'accordo di C",
3:{q:"Che cos'è un arpeggio?",o:["Una pennata forte","Suonare le note di un accordo una dopo l'altra","Un cambio di accordo rapido","Un tipo di plettro"],w:"Arpeggio = «accordo spezzato»: le note si suonano in successione e non insieme."},
4:"Suona un arpeggio su C, Am e F, quattro movimenti ciascuno."}},

"ukulele-7":{title:"Melodia sull'ukulele",goal:"Suonare melodia, non solo accompagnamento",b:{
0:"L'ukulele sa suonare anche melodie. Useremo le corde do, mi e la.",
1:"Brilla, brilla, stellina — melodia",
2:"All'inizio segna le note sul manico con piccoli adesivi: è una scorciatoia perfettamente legittima.",
3:{q:"Qual è il vantaggio di suonare melodie sullo strumento?",o:["È più facile degli accordi","Allena l'orecchio e la conoscenza di dove sta ogni nota","Suona più forte","Non c'è vantaggio"],w:"Suonare la melodia collega l'orecchio al manico: un'abilità insostituibile."},
4:"Suona la melodia due volte lentamente."}},

"ukulele-8":{title:"Cantare e suonare insieme",goal:"Combinare accompagnamento e canto",b:{
0:"È l'abilità che ti rende la persona invitata a suonare intorno al fuoco. Il segreto è l'<b>automatismo</b>: la mano deve suonare senza che tu ci pensi.",
1:["Suona l'accompagnamento finché non riesci a sostenere una conversazione mentre lo fai.","Di' le parole a tempo, senza cantare.","Canticchia la melodia mentre suoni.","Solo adesso: canta parole e melodia insieme."],
2:"Se il canto «trascina» la mano, smetti di cantare, stabilizza la mano e riprova. La mano è l'ancora.",
3:{q:"Qual è la condizione per cantare e suonare insieme?",o:["Una bella voce","Che l'accompagnamento sia del tutto automatico","Accordi complicati","Un metronomo"],w:"Un accompagnamento automatico libera l'attenzione per il canto."},
4:"Suona l'accompagnamento e canticchia una melodia per un minuto intero."}},

"ukulele-9":{title:"Brano finale e uno sguardo avanti",goal:"Suonare un brano completo dall'inizio alla fine",b:{
0:"Hava Nagila — melodia tradizionale (pubblico dominio)",
1:"I passi successivi sull'ukulele: accordi barré, la tecnica del «chunk» (smorzamento ritmico) e fingerpicking avanzato.",
2:"Trova qualcuno con cui suonare. Suonare insieme migliora il senso del ritmo molto più di qualsiasi studio da soli.",
3:{q:"Quale passo è consigliato dopo aver padroneggiato gli accordi aperti?",o:["Cambiare strumento","Accordi barré e ritmi avanzati","Smettere di studiare","Imparare solo la notazione"],w:"Il barré apre tutto il manico e permette di suonare in qualsiasi tonalità."},
4:"Registrati mentre suoni un brano completo."}},

/* ===================== FLAUTO DOLCE ===================== */
"recorder-1":{title:"Respirazione e prima diteggiatura",goal:"Produrre un suono pulito e suonare il si",b:{
0:"Il flauto dolce è lo strumento perfetto per iniziare: economico, leggero, e non richiede forza né mani grandi.",
1:["Tieni il flauto a circa 45 gradi dal corpo.","Mano sinistra in alto — sempre! È l'errore più frequente.","Appoggia la punta del becco sul labbro inferiore e chiudi le labbra con delicatezza, senza mordere.","Soffia piano sussurrando «tu»: è il colpo di lingua con cui inizia ogni nota."],
2:"Soffiare troppo forte darà un suono stridulo e acuto. Il flauto ha bisogno di <b>pochissima</b> aria. Meno è meglio.",
3:"La nota si (B)",
4:"Prima nota: il pollice sinistro chiude il foro posteriore, l'indice sinistro quello in alto. Ecco fatto: questo è il si.",
5:{q:"Quale mano sta sempre in alto sul flauto dolce?",o:["La destra","La sinistra","Dipende se sei mancino","Non ha importanza"],w:"La mano sinistra sta sempre in alto, su tutti i legni."},
6:"Suona 10 si lunghi e stabili, di 4 secondi ciascuno."}},

"recorder-2":{title:"Tre note — si, la, sol",goal:"Suonare una melodia breve",b:{
0:["<b>Si (B)</b> — pollice + dito 1 della mano sinistra.","<b>La (A)</b> — si aggiunge il dito 2 sinistro.","<b>Sol (G)</b> — si aggiunge il dito 3 sinistro."],
1:"Esercizio a tre note",
2:"Assicurati che le dita chiudano i fori <b>completamente</b>, con il polpastrello e non con la punta. Un foro semiaperto produce uno strillo.",
3:{q:"Cosa succede quando un foro non è chiuso del tutto?",o:["Il suono è troppo grave","Il suono strilla o fischia","Non succede nulla","Il flauto si rovina"],w:"L'aria che sfugge da un foro semiaperto crea un fischio."},
4:"Suona l'esercizio 5 volte senza alcuna stecca."}},

"recorder-3":{title:"Il primo brano",goal:"Suonare una melodia conosciuta",b:{
0:"Mary Had a Little Lamb — melodia popolare (pubblico dominio)",
1:"Questo brano usa le note già imparate più do e re: entrano le dita della mano destra.",
2:"Canticchia prima la melodia e solo dopo suonala sullo strumento. Un orecchio che conosce la melodia guida le dita.",
3:{q:"Quale passo è consigliato prima di suonare un brano nuovo?",o:["Suonarlo veloce","Canticchiarlo e conoscere la melodia","Leggere le note ad alta voce","Accordare lo strumento"],w:"Un orecchio che conosce la melodia individua subito l'errore."},
4:"Suona il brano per intero due volte."}},

"recorder-4":{title:"Colpo di lingua e articolazione",goal:"Separare le note in modo pulito",b:{
0:"Senza colpo di lingua tutte le note si fondono in un unico suono lungo. La lingua è la punteggiatura del tuo suonare.",
1:["<b>«Tu»</b> — inizio netto per ogni nota.","<b>«Du»</b> — inizio morbido, per i passaggi cantabili.","<b>Legato</b> — colpo di lingua solo sulla prima nota del gruppo.","<b>Staccato</b> — note brevi e separate."],
2:"Staccato contro legato",
3:{q:"A cosa serve la lingua quando si suona il flauto dolce?",o:["A mantenere il suono acuto","A separare e iniziare le note in modo pulito","A suonare più forte","Ad accordare lo strumento"],w:"La lingua definisce l'inizio di ogni nota: senza di essa l'esecuzione risulta impastata."},
4:"Suona una scala completa una volta staccato e una volta legato."}},

"recorder-5":{title:"La scala completa di do maggiore",goal:"Suonare un'ottava intera",b:{
0:"Scala di do maggiore",
1:"Una scala completa richiede la collaborazione di entrambe le mani. La difficoltà principale: il passaggio dalle note della sinistra a quelle della destra.",
2:"Esercita solo il passaggio problematico (sol→fa) venti volte, invece di risuonare tutta la scala all'infinito.",
3:{q:"Cosa conviene fare con un passaggio difficile?",o:["Risuonare tutto il passaggio all'infinito","Isolare le due note problematiche e lavorare solo su quelle","Saltare il passaggio","Rallentare tutto il brano"],w:"Il lavoro mirato è molte volte più efficace del ripetere l'insieme."},
4:"Suona la scala andata e ritorno 5 volte con il metronomo a 60."}},

"recorder-6":{title:"La seconda ottava",goal:"Produrre note acute con il pollice",b:{
0:"Per salire di un'ottava il pollice «pizzica» il foro posteriore, aprendolo appena. È la tecnica dell'<b>ottavazione</b>.",
1:["Fai scivolare il pollice così che l'unghia apra una piccola fessura.","Aumenta leggermente la pressione dell'aria.","Suona sol grave e sol acuto alternandoli."],
2:"Ottave",
3:"Suono stridulo? La fessura è troppo grande. Suono grave? La fessura è chiusa. La differenza è di un millimetro.",
4:{q:"Qual è il ruolo del pollice sinistro nelle note acute?",o:["Chiudere del tutto","Aprire una piccola fessura","Solo reggere lo strumento","Aprire del tutto"],w:"Una piccola fessura cambia il modo di vibrazione e alza il suono di un'ottava."},
5:"Suona l'esercizio delle ottave 10 volte."}},

"recorder-7":{title:"Diesis e bemolli",goal:"Suonare i semitoni",b:{
0:"Sul flauto dolce i semitoni si ottengono con <b>diteggiature a forcella</b>: chiudendo fori non consecutivi.",
1:"Il fa diesis (F#) è la nota più importante da imparare: serve in qualsiasi brano in sol maggiore.",
2:"Scala di sol maggiore (con F#)",
3:{q:"Che cos'è una diteggiatura a forcella?",o:["Chiudere tutti i fori","Chiudere fori non consecutivi per creare un semitono","Aprire tutti i fori","Una diteggiatura a due mani"],w:"Saltare un foro in mezzo alla diteggiatura abbassa la nota di un semitono."},
4:"Suona la scala di sol maggiore andata e ritorno."}},

"recorder-8":{title:"Espressione, respirazione e fraseggio",goal:"Suonare musicalmente e non meccanicamente",b:{
0:"Respirare non è solo un bisogno fisico: è punteggiatura. Si respira alla fine di una frase musicale, non a metà di una parola.",
1:["Segna sullo spartito dove respirerai, prima di iniziare a suonare.","Inspira dalla bocca, in fretta e in silenzio.","Non respirare in mezzo a una nota lunga.","Chiudi la frase con un ammorbidimento delicato."],
2:"Suona una frase musicale come se pronunciassi una frase: inizio, culmine e finale ammorbidito.",
3:{q:"Dov'è giusto respirare?",o:["Ogni due movimenti","Alla fine di una frase musicale","Ogni volta che finisce l'aria","In mezzo a una nota lunga"],w:"Un respiro pianificato a fine frase preserva la linea musicale."},
4:"Suona un brano intero segnando in anticipo tre punti di respiro."}},

"recorder-9":{title:"Brano finale — Inno alla gioia",goal:"Suonare un'opera classica completa",b:{
0:"Inno alla gioia — Beethoven (pubblico dominio)",
1:"Il flauto dolce è un'ottima porta d'ingresso verso altri strumenti a fiato: flauto traverso, clarinetto, sassofono. Respirazione e colpo di lingua si trasferiscono quasi identici.",
2:{q:"Quale strumento è considerato la continuazione naturale dopo il flauto dolce?",o:["La batteria","Il flauto traverso o il clarinetto","Il pianoforte","Il violino"],w:"La tecnica di respirazione e di articolazione passa direttamente ai legni."},
3:"Suona il brano dall'inizio alla fine senza fermarti."}},

/* ===================== BATTERIA ===================== */
"drums-1":{title:"Il ritmo — il linguaggio del corpo della musica",goal:"Mantenere una pulsazione stabile",b:{
0:"Per iniziare non serve una batteria. Un tavolo, due mani o due matite bastano perfettamente per le prime tre lezioni.",
1:"Pulsazioni in semiminime — contare a quattro",
2:["Metti il metronomo a 72.","Batti le mani esattamente su ogni pulsazione.","Conta ad alta voce: 1-2-3-4.","Accentua la prima pulsazione."],
3:"<b>La prova:</b> se anticipi o trascini, senti il metronomo «spostarsi». Se sei preciso, quasi scompare sotto il tuo battito.",
4:{q:"Qual è il segno che sei preciso con il metronomo?",o:["Il metronomo suona più forte","Il metronomo quasi scompare sotto il tuo suono","Stai suonando veloce","Non c'è modo di saperlo"],w:"Quando il tuo colpo cade esattamente sul click, i due suoni si fondono."},
5:"Due minuti di battiti precisi a 72."}},

"drums-2":{title:"Il groove di base",goal:"Suonare il groove presente nell'80 % dei brani",b:{
0:"Il groove di base ha tre componenti: <b>charleston</b> (crome continue), <b>cassa</b> (movimenti 1 e 3), <b>rullante</b> (movimenti 2 e 4).",
1:null,
2:["Inizia con il solo charleston: 1-e-2-e-3-e-4-e.","Aggiungi la cassa sui movimenti 1 e 3.","Aggiungi il rullante sui movimenti 2 e 4.","Suona tutti e tre insieme, lentamente."],
3:"Se una mano o un piede «fa cadere» gli altri, abbassa la velocità del 20 %. La velocità è un risultato, non un obiettivo.",
4:{q:"Su quali movimenti cade il rullante nel groove di base?",o:["1 e 3","2 e 4","Su tutti","Solo sull'1"],w:"Il rullante su 2 e 4 è il «backbeat»: il polso del rock e del pop."},
5:"Suona il groove per 16 battute di fila a 70."}},

"drums-3":{title:"Indipendenza degli arti",goal:"Separare le mani dai piedi",b:{
0:"L'indipendenza è la capacità di far fare a ogni arto qualcosa di diverso nello stesso momento. Si impara: nessuno ci nasce.",
1:["Suona solo charleston e rullante.","Solo charleston e cassa.","Solo cassa e rullante.","Unisci tutti e tre.","Sposta la cassa sul «4-e» e senti il cervello opporsi. È esattamente questo l'allenamento."],
2:"Esercizio di indipendenza",
3:"Lavora sull'indipendenza 5 minuti al giorno: è meglio di un'ora una volta a settimana. È apprendimento motorio e richiede ripetizioni distribuite.",
4:{q:"Qual è il modo efficace di sviluppare l'indipendenza?",o:["Suonare veloce","Scomporre in coppie di arti e unire gradualmente","Suonare brani interi","Ascoltare musica"],w:"Scomporre in coppie permette al cervello di costruire lo schema passo dopo passo."},
5:"Lavora su tre coppie di arti, un minuto ciascuna."}},

"drums-4":{title:"Gli stacchi — il passaggio tra le sezioni",goal:"Suonare uno stacco di una battuta",b:{
0:"Uno <b>stacco (fill)</b> è un breve passaggio che segna la transizione tra le parti del brano. Lo stacco di base: quattro coppie di crome tra rullante e tom.",
1:"Uno stacco di una battuta",
2:"La regola più importante di uno stacco: <b>rientrare in tempo</b>. Uno stacco spettacolare che arriva in ritardo è peggio di uno semplice che cade preciso.",
3:{q:"Qual è la cosa più importante in uno stacco?",o:["Che sia veloce","Che finisca esattamente in tempo per il movimento 1","Che sia lungo","Che usi tutti i tamburi"],w:"Lo stacco serve il brano: la precisione del rientro conta più del contenuto."},
4:"Suona 4 battute di groove + una battuta di stacco, quattro volte."}},

"drums-5":{title:"Dinamica e peso",goal:"Controllare la forza dei colpi",b:{
0:"Un buon batterista non colpisce forte: colpisce <b>giusto</b>. Un buon groove contiene almeno tre livelli di volume.",
1:["Charleston — piano e uniforme.","Cassa — medio, si sente nella pancia.","Rullante — forte e netto; è ciò che si sente.","Prova a suonare lo stesso groove al 30 % di volume e poi al 90 %."],
2:"Il controllo del volume nasce dall'impugnatura: una presa rilassata con un «punto d'appoggio» tra pollice e dito dà un colpo libero e rimbalzante.",
3:{q:"Quale elemento del groove deve essere il più forte?",o:["Il charleston","Il rullante","Tutto allo stesso volume","La cassa"],w:"Il rullante è il «click» del groove e perciò emerge."},
4:"Suona il groove a tre livelli di volume diversi."}},

"drums-6":{title:"Groove in stili diversi",goal:"Conoscere quattro groove",b:{
0:"Rock",1:"Shuffle / blues",2:"Valzer",3:"Funk (semicrome)",
4:"Lo stile non è solo uno schema: è anche una sensazione. Lo shuffle ondeggia, il rock è dritto, il funk è netto e spezzato.",
5:{q:"Cosa distingue gli stili ritmici tra loro?",o:["Solo la velocità","Lo schema dei colpi e la sensazione (dritto o ondeggiante)","Il tipo di tamburi","Il volume"],w:"Lo schema e il «groove feeling» sono ciò che definisce lo stile."},
6:"Suona ciascuno dei quattro groove per 8 battute."}},

"drums-7":{title:"Leggere la notazione per batteria",goal:"Decifrare uno schema di groove",b:{
0:"La notazione per batteria usa lo stesso pentagramma, ma ogni linea rappresenta un tamburo diverso: charleston in alto (X), rullante al centro, cassa in basso.",
1:["Linea superiore con una X — charleston.","Il terzo spazio — rullante.","Lo spazio inferiore — cassa.","Conta la battuta: 1 e 2 e 3 e 4 e, e segna cosa cade dove."],
2:{q:"Cosa significa una X nella notazione per batteria?",o:["Cassa","Un piatto o il charleston","Rullante","Una pausa"],w:"Una testa di nota a forma di X indica uno strumento metallico: charleston, crash o ride."},
3:"Scrivi il groove di base su carta in notazione."}},

"drums-8":{title:"Suonare su un brano",goal:"Tenere il ritmo insieme alla musica",b:{
0:"Il batterista è l'orologio del gruppo. Per entrare: trova il movimento 1, conta una battuta intera ed entra.",
1:["Ascolta il brano e trova il backbeat (2 e 4).","Batti le mani insieme per 30 secondi.","Suona il groove di base sopra il brano.","Aggiungi uno stacco ogni 8 battute."],
2:"Non riempire ogni secondo. I silenzi del batterista contano esattamente quanto i colpi.",
3:{q:"Qual è il ruolo centrale del batterista in un gruppo?",o:["Essere il più forte","Tenere un ritmo stabile e guidare i passaggi","Suonare assoli","Cambiare gli accordi"],w:"La stabilità del ritmo è la base su cui si appoggia tutto il gruppo."},
4:"Suona su un brano che ti piace per 3 minuti."}},

"drums-9":{title:"Chiusura e uno sguardo avanti",goal:"Combinare groove, stacchi e dinamica",b:{
0:"Hai completato le basi: groove, indipendenza, stacchi, dinamica e stili.",
1:["Suona 8 battute di groove rock.","Uno stacco di una battuta.","8 battute di shuffle.","Uno stacco.","Chiudi con un crash sul movimento 1."],
2:"La tappa successiva: i rudimenti (paradiddle, ruff, rullo doppio): sono le «scale» del batterista.",
3:{q:"Cosa sono i rudimenti?",o:["Tipi di tamburi","Schemi di colpi di base da cui si costruisce tutto","Ritmi latini","Tipi di bacchette"],w:"I rudimenti sono i mattoni della tecnica batteristica."},
4:"Registrati mentre suoni una sequenza completa."}},

/* ===================== BASSO ===================== */
"bass-1":{title:"Incontro con il basso",goal:"Suonare le corde a vuoto a tempo",b:{
0:"Il basso elettrico è il ponte tra la batteria e la chitarra. Quattro corde: <b>E-A-D-G</b>, un'ottava sotto le quattro corde grosse di una chitarra.",
1:"Le corde a vuoto",
2:["Mano destra: indice e medio si alternano — la «tecnica a due dita».","Il pollice appoggia sul pickup.","Mano sinistra: un dito per tasto.","Suona ogni corda a vuoto quattro volte."],
3:"<b>La prima regola del bassista:</b> una nota pulita e breve nel posto giusto vale più di dieci note impressionanti.",
4:{q:"Qual è l'accordatura standard di un basso a quattro corde?",o:["G-C-E-A","E-A-D-G","E-A-D-G-B-E","D-A-D-G"],w:"E-A-D-G: le stesse delle quattro corde grosse della chitarra, un'ottava sotto."},
5:"Suona 8 movimenti su ogni corda a vuoto con il metronomo a 70."}},

"bass-2":{title:"La tua prima linea di basso",goal:"Suonare la fondamentale di ogni accordo",b:{
0:"Il compito di base del bassista: suonare la <b>fondamentale</b> dell'accordo che suona la chitarra, sul primo movimento di ogni battuta.",
1:"Linea di basso per la successione G-C-D",
2:["Accordo G → suona sol.","Accordo C → suona do.","Accordo D → suona re.","Un movimento lungo per battuta, poi quattro semiminime."],
3:"Un buon bassista sa dov'è ogni nota senza pensarci. Esercitati: «dov'è il fa?» e trovalo in tre punti diversi.",
4:{q:"Che cos'è la fondamentale?",o:["La nota più acuta dell'accordo","La nota che dà il nome all'accordo","La prima nota della scala","La corda grossa"],w:"Nell'accordo di G la fondamentale è sol. È la nota di base del bassista."},
5:"Suona le fondamentali della successione G-C-D-G, quattro movimenti ciascuna."}},

"bass-3":{title:"Ritmo e groove con la batteria",goal:"Incastrare il basso con la cassa",b:{
0:"La magia di un gruppo nasce quando basso e cassa suonano <b>esattamente insieme</b>. Si chiama «lock».",
1:"Schema di cassa su cui esercitarsi",
2:["Ascolta lo schema della cassa.","Suona una nota esattamente su ogni colpo.","Non aggiungere note: sii solo preciso.","Ora aggiungi una nota di passaggio prima della battuta successiva."],
3:"Se suoni tra i movimenti e non sei sicuro, non suonare. Un silenzio preciso è meglio di una nota imprecisa.",
4:{q:"Con quale strumento il basso deve essere più sincronizzato?",o:["La chitarra","La cassa","La voce","Il pianoforte"],w:"La coppia basso + cassa è la base ritmica di qualsiasi formazione."},
5:"Suona sullo schema di cassa per due minuti."}},

"bass-4":{title:"Le note sul manico",goal:"Trovare ogni nota in due punti",b:{
0:"Sulla corda mi: tasto 1 = fa, tasto 3 = sol, tasto 5 = la. Sulla corda la: tasto 2 = si, tasto 3 = do.",
1:"<b>La regola dell'ottava:</b> la stessa nota si trova anche due corde più in basso e due tasti più avanti. È la scorciatoia più utile sul basso.",
2:"La stessa nota in due ottave",
3:{q:"Dov'è l'ottava di una nota sul basso?",o:["Sulla stessa corda 12 tasti più su, oppure due corde sotto e due tasti avanti","Sullo stesso tasto della corda vicina","Non c'è una regola fissa","Tre tasti indietro"],w:"Entrambe sono corrette, e lo schema «due e due» è il più rapido da usare."},
4:"Scegli una nota e trovala in tre punti diversi del manico."}},

"bass-5":{title:"Walking bass",goal:"Collegare gli accordi con note di passaggio",b:{
0:"<b>Walking bass</b>: una linea di basso che suona quattro note per battuta e collega gli accordi passo dopo passo.",
1:"Una walking line semplice",
2:["Parti dalla fondamentale.","Suona note dell'accordo (fondamentale, terza, quinta).","Arriva a una nota che dista un passo dalla fondamentale successiva.","Atterra sulla fondamentale successiva sul movimento 1."],
3:{q:"A cosa serve una nota di passaggio in una walking bass?",o:["A riempire spazio","A condurre dolcemente alla fondamentale dell'accordo successivo","A suonare veloce","A sostituire la batteria"],w:"Una nota di passaggio crea attesa e un'attrazione naturale verso l'accordo successivo."},
4:"Suona una walking line sulla successione C-F-G-C."}},

"bass-6":{title:"Tecniche della mano destra",goal:"Conoscere dita, plettro e slap",b:{
0:["<b>Con le dita:</b> il suono più caldo e diffuso.","<b>Con il plettro:</b> suono netto e incisivo, adatto a rock e punk.","<b>Slap:</b> il pollice colpisce la corda grossa, il dito «strappa» quella sottile: il suono funk caratteristico."],
1:"Schema di slap di base",
2:"Nello slap il pollice ruota attorno a un asse: non «punge». Il rimbalzo fa parte del movimento.",
3:{q:"Che cos'è la tecnica dello slap?",o:["Suonare con il plettro","Un colpo di pollice e uno strappo di dito","Suonare a due mani","Smorzare le corde"],w:"La combinazione di colpo di pollice e strappo di dito crea il suono percussivo."},
4:"Suona otto battute con ciascuna delle tecniche."}},

"bass-7":{title:"Smorzamento e controllo del rumore",goal:"Suonare pulito, senza corde che risuonano",b:{
0:"Il problema numero uno sul basso non sono le note sbagliate, ma il <b>rumore</b>: corde che continuano a vibrare.",
1:["Il pollice della mano destra appoggia sulla corda grossa e la smorza.","Le dita della mano sinistra che non suonano sfiorano le corde vicine.","Dopo ogni nota, pensa a come la <b>fermi</b>, non solo a come la inizi.","Suona una nota, smorzala del tutto e solo allora suona la successiva."],
2:{q:"Qual è il problema più frequente nel suonare il basso?",o:["Le note sbagliate","Il rumore delle corde non smorzate","Il tempo lento","Le corde sottili"],w:"Il controllo del rumore è la differenza tra un dilettante e un professionista."},
3:"Suona nota-silenzio-nota-silenzio per un minuto."}},

"bass-8":{title:"Una linea di basso per un brano intero",goal:"Costruire una linea di basso autonoma",b:{
0:"Una buona linea di basso si costruisce in tre fasi: solo fondamentali → fondamentali a tempo → aggiunta di note di passaggio e varianti.",
1:"Riff di blues (esercizio originale)",
2:"Ascolta i bassisti dei brani che ami. Nota quanto poco suonano — e quanto suona giusto.",
3:{q:"Qual è l'ordine corretto per costruire una linea di basso?",o:["Improvvisare subito","Fondamentali → ritmo → note di passaggio","Copiare un assolo","Partire dalla nota più acuta"],w:"La costruzione graduale mantiene la linea stabile e al servizio del brano."},
4:"Costruisci una linea di basso per un brano che conosci, nelle tre fasi."}},

"bass-9":{title:"Chiusura e uno sguardo avanti",goal:"Suonare con un gruppo",b:{
0:"Hai completato le basi. Un bassista con tempo stabile, suono pulito e comprensione armonica è ricercato in qualsiasi band.",
1:["Studia con il metronomo ogni giorno, anche solo 5 minuti.","Registrati: l'orecchio coglie ciò che la mano non sente.","Suona con altre persone il prima possibile.","Impara la scala maggiore e la minore naturale su tutto il manico."],
2:{q:"Qual è la qualità più importante in un bassista?",o:["La velocità","Tempo stabile e suono pulito","Conoscere la notazione","Attrezzatura costosa"],w:"È la stabilità a far suonare bene tutto il gruppo."},
3:"Suona un brano completo dall'inizio alla fine con il metronomo."}}

});

/* ---- i quattro nuovi strumenti ---- */
I18N.registerLessons("it", {

"violin-1":{title:"Impugnatura e corde vuote",goal:"Produrre un suono pulito su tutte e quattro le corde",b:{
0:"Il violino è lo strumento in cui <b>l'orecchio guida il dito</b>. Non ci sono tasti, quindi ogni nota si costruisce ascoltando — ed è proprio questo a renderlo il miglior maestro per l'orecchio.",
1:"Quattro corde, dalla più grossa alla più sottile: <b>sol, re, la, mi</b>. Fra ogni coppia c'è una quinta.",
3:["Appoggia il violino sulla clavicola, con la mascella sulla mentoniera.","La mano sinistra tiene il manico con leggerezza: non lo stringe.","L'archetto poggia sulla corda a metà strada fra il ponticello e la tastiera.","Tira l'archetto lentamente e con pressione uniforme. Un suono pulito vale più di uno forte."],
4:"Un fischio? Una di tre cose: pressione irregolare, archetto troppo lontano dal ponticello, oppure velocità che cambia. Rallenta.",
5:{q:"Come sono accordate le corde del violino?",o:["Per quarte","Per quinte","Per ottave","Per terze"],w:"Sol-re-la-mi: una quinta fra ogni coppia di corde vicine."},
6:"Suona ogni corda vuota otto volte con arcata intera, senza fischi."}},

"violin-2":{title:"Il primo dito",goal:"Suonare quattro note nuove",b:{
0:"Il primo dito si appoggia a <b>un tono intero</b> dalla corda vuota. È il punto di riferimento di tutta la mano.",
2:"Attacca un pezzetto di nastro dove cade il primo dito. Non è barare: è così che imparano tutti i violinisti del mondo nel primo anno.",
3:"Corda vuota e primo dito",
4:{q:"Qual è la distanza fra la corda vuota e il primo dito?",o:["Un semitono","Un tono intero","Un tono e mezzo","Due toni"],w:"Un tono intero, ed è la prima distanza che l'orecchio impara."},
5:"Suona l'esercizio lentamente e controlla ogni nota con l'accordatore dell'app."}},

"violin-3":{title:"Una prima melodia",goal:"Suonare un brano intero su due corde",b:{
0:"Con le corde vuote e il primo dito puoi già suonare una melodia vera.",
2:"Esercizio su due corde",
3:"<b>La regola del primo anno:</b> lento e pulito batte sempre veloce e confuso.",
4:{q:"Che cosa conta di più in questa fase?",o:["Suonare veloce per progredire","Suonare lentamente e ascoltare ogni nota","Saltare le note difficili","Suonare il più forte possibile"],w:"Sul violino ogni imprecisione si sente subito. Rallentare è la scorciatoia."},
5:"Suona la melodia cinque volte, ogni volta un po' più veloce."}},

"violin-4":{title:"Tre dita: la tua prima scala",goal:"Suonare la scala di re maggiore su due corde",b:{
0:"Sul violino la scala non si costruisce con i tasti ma con uno <b>schema fisso di dita</b>. Una volta che la mano lo impara, si ripete su ogni corda.",
1:"Sulla corda re: dito 1 = mi, dito 2 = fa diesis, dito 3 = sol. Nota che le dita 2 e 3 <b>si toccano</b>: è il segnale che lo schema è corretto.",
3:"Scala di re maggiore",
4:"Le dita 2 e 3 stanno unite in una scala maggiore. Se si apre uno spazio fra loro, il fa diesis risulterà calante.",
5:{q:"Che cosa caratterizza la posizione delle dita 2 e 3 in maggiore?",o:["Un ampio spazio fra loro","Si toccano","Il dito 3 non si usa","Non c'è una regola fissa"],w:"La loro vicinanza è il semitono fra il terzo e il quarto grado."},
6:"Suona la scala nei due sensi dieci volte, lentamente, controllando ogni nota con l'accordatore."}},

"violin-5":{title:"La distribuzione dell'arco",goal:"Controllare la durata e la forza del suono",b:{
0:"L'arco è il <b>respiro</b> del violino. Una nota lunga chiede un arco lento, una corta poco arco — e la pressione resta costante.",
1:["Individua tre zone: tallone, metà, punta.","Suona una semibreve con arcata intera, dal tallone alla punta, in quattro secondi.","Suona quattro semiminime nella stessa arcata: ciascuna un quarto del percorso.","Ora suona crome usando solo la metà dell'arco."],
2:"Distribuzione dell'arco",
3:"Il suono si indebolisce alla fine dell'arco? La pressione cala insieme al braccio. Tienila uniforme fino alla punta.",
4:{q:"Che cosa determina la durata di una nota sul violino?",o:["La pressione del dito","La velocità dell'arco","Come si tiene lo strumento","Lo spessore della corda"],w:"La velocità dell'arco fissa la durata; la pressione il volume."},
5:"Suona una scala intera con arcata intera per nota, poi con mezza arcata."}},

"violin-6":{title:"Seconda corda e cambi",goal:"Passare fra le corde senza rumore",b:{
0:"Il passaggio fra le corde è il punto in cui si sente la differenza fra un principiante e un musicista. Il segreto: <b>il braccio inizia a muoversi prima che la nota cambi</b>.",
2:"Esercizio di cambi",
3:"Se durante il passaggio si sente un suono doppio, l'archetto ha toccato due corde. A cambiare dev'essere l'angolo, non la pressione.",
4:{q:"Che cosa provoca un suono doppio nel cambio di corda?",o:["Troppa pressione","L'archetto tocca due corde","Lo strumento è scordato","Il dito è fuori posto"],w:"È l'angolo dell'archetto a separare le corde."},
5:"Suona l'esercizio dieci volte, perfettamente pulito."}},

"violin-7":{title:"Un primo vibrato",goal:"Conoscere il movimento del vibrato",b:{
0:"Il vibrato è un <b>piccolo dondolio del dito</b> che scalda il suono. Si insegna più tardi di quanto si creda, e non a caso: nasconde l'imprecisione, quindi prima si impara a suonare pulito senza.",
1:["Metti il dito 2 sulla corda la, senza archetto.","Fai dondolare la mano avanti e indietro dal polso, non dal dito.","Il dito resta al suo posto: cambia solo leggermente l'altezza.","Aggiungi l'archetto solo quando il movimento è fluido."],
2:"Un vibrato veloce e stretto sembra un tremito. Lento e ampio sembra un canto. Comincia lento.",
3:{q:"Da dove nasce il movimento del vibrato?",o:["Dal dito","Dal polso","Solo dal gomito","Dalla spalla"],w:"Il movimento nasce dal polso; il dito lo accompagna soltanto."},
4:"Esercita il movimento un minuto senza archetto e poi un minuto con l'archetto."}},

"violin-8":{title:"Una melodia completa",goal:"Suonare un brano noto dall'inizio alla fine",b:{
0:"Ora si unisce tutto: lo schema delle dita, la distribuzione dell'arco e i cambi di corda.",
1:"Melodia per due corde",
2:"Suona prima senza archetto, in pizzicato, per verificare che le dita siano al loro posto. Poi aggiungi l'archetto.",
3:{q:"Che cosa conviene verificare prima di aggiungere l'archetto?",o:["Il volume","Che le dita siano al posto giusto","Il tempo","La posizione della testa"],w:"Il pizzicato isola la mano sinistra e rivela subito le imprecisioni."},
4:"Suona la melodia cinque volte: due in pizzicato e tre con l'arco."}},

"violin-9":{title:"Bilancio e prossimi passi",goal:"Suonare con sicurezza e sapere dove andare",b:{
0:"Hai completato le basi: l'impugnatura, le corde vuote, lo schema delle dita, la distribuzione dell'arco e i cambi. Tutto il resto si costruisce su questo.",
1:"Che cosa viene dopo: <b>la seconda posizione</b> (spostare tutta la mano lungo il manico), <b>suonare su due corde insieme</b> e <b>leggere la musica</b> mentre si suona.",
2:"Brano finale",
3:"<b>L'errore classico del secondo anno:</b> accelerare prima che il suono sia pulito. Suona tutto con metronomo lento e supererai chi ha avuto fretta.",
4:{q:"Qual è il passo naturale successivo sul violino?",o:["Suonare più veloce","La seconda posizione e la lettura","Cambiare strumento","Rinunciare all'archetto"],w:"La seconda posizione apre il resto del manico, e la lettura apre il repertorio."},
5:"Suona il brano finale e registrati. Riascoltarsi è il maestro più onesto."}},

"harmonica-1":{title:"Soffiare e aspirare",goal:"Produrre un suono pulito da un solo foro",b:{
0:"L'armonica è l'unico strumento in cui <b>sia soffiare sia aspirare producono un suono</b>, e due suoni diversi dallo stesso foro.",
1:"Un'armonica in do ha dieci fori e venti ance. Il quarto foro è il punto di partenza di quasi ogni melodia.",
3:["Tieni l'armonica fra pollice e indice, con i numeri verso l'alto.","Arrotonda le labbra come per dire «u».","Soffia delicatamente nel foro quattro: esce do.","Ora aspira dallo stesso foro: esce re."],
4:"Escono più note insieme? La bocca è troppo aperta. Restringi le labbra finché non resta una sola nota pulita.",
5:{q:"Che cosa distingue l'armonica dagli altri strumenti a fiato?",o:["Non ha note acute","Soffiare e aspirare producono entrambi un suono","Va riaccordata ogni volta","Bisogna premere dei tasti"],w:"In ogni foro ci sono due ance: una per soffiare e una per aspirare."},
6:"Alterna soffio e aspirazione sul foro 4, venti volte, con suono pulito."}},

"harmonica-2":{title:"Quattro fori: la tua prima melodia",goal:"Suonare una melodia conosciuta",b:{
0:"I fori dal 4 al 7 contengono una scala completa di do maggiore. Lì vive quasi ogni canzone popolare.",
2:"Guarda la freccia sopra lo schema: verso l'alto si soffia, verso il basso si aspira. È tutto ciò che serve ricordare.",
3:"La scala sull'armonica",
4:{q:"In quali fori si trova la scala completa di do maggiore?",o:["Dall'1 al 4","Dal 4 al 7","Dal 7 al 10","In tutti"],w:"Solo dal 4 al 7 la scala è completa senza bending."},
5:"Suona la scala nei due sensi dieci volte."}},

"harmonica-3":{title:"La tua prima canzone",goal:"Suonare una melodia intera a memoria",b:{
0:"Ora si unisce tutto. Questa melodia usa solo i fori dal 4 al 6.",
2:"Melodia per quattro fori",
3:"Prova a suonare senza guardare i numeri. Sull'armonica l'orecchio trova il foro più in fretta dell'occhio.",
4:{q:"Qual è il modo migliore per imparare una melodia sull'armonica?",o:["Memorizzare i numeri dei fori","Ascoltare e cercare a orecchio","Contare i respiri","Leggere la musica"],w:"L'armonica è nata per suonare a orecchio: è la sua forza."},
5:"Suona la melodia tre volte a occhi chiusi."}},

"harmonica-4":{title:"Suonare un solo foro",goal:"Produrre una nota pulita senza le vicine",b:{
0:"Finora forse suonavano più note insieme. Ora impari a tirarne fuori <b>una sola</b>, ed è questo che trasforma il rumore in melodia.",
1:["Infila l'armonica più a fondo fra le labbra, come se stessi bevendo.","La lingua sta in basso e rilassata.","Restringi l'apertura delle labbra finché non suona una sola nota.","Verifica: soffia nel foro 4; se senti un accordo, le labbra sono troppo larghe."],
3:"Un secondo metodo, il <b>blocco con la lingua</b>: copri tre fori con la bocca e bloccane due con la lingua. Ne resta uno aperto.",
4:{q:"Perché suonano più note insieme?",o:["L'armonica è rotta","L'apertura delle labbra è troppo larga","Soffi troppo forte","I fori sono ostruiti"],w:"Una bocca larga copre più fori contemporaneamente."},
5:"Suona i fori 4, 5 e 6 soffiando: ciascuno separatamente e pulito, venti volte."}},

"harmonica-5":{title:"La seconda ottava",goal:"Estendere l'estensione ai fori dall'1 al 7",b:{
0:"I fori bassi (1–3) danno i suoni profondi, quelli alti (7–10) i suoni acuti. La maggior parte delle melodie vive in mezzo.",
2:"Nota una curiosità: dal foro 7 in su <b>l'aspirazione è più grave del soffio</b>, al contrario dei fori bassi. È una proprietà dell'accordatura, non un guasto.",
3:"Estensione completa",
4:{q:"Che cosa cambia dal foro 7 in su?",o:["Niente","L'aspirazione diventa più grave del soffio","Non si può aspirare","Il suono è più debole"],w:"È un'inversione insita nell'accordatura Richter."},
5:"Suona tutti i soffi dal foro 1 al 10 e ritorno."}},

"harmonica-6":{title:"Ritmo e respirazione",goal:"Suonare a tempo senza restare senza fiato",b:{
0:"Sull'armonica il respiro è insieme suono e carburante. Suona troppo a lungo in una direzione e resterai senza aria.",
1:"Alternanza di soffio e aspirazione",
2:"<b>La regola:</b> se la melodia chiede tre soffi di fila, cerca un punto per cambiare direzione. Quasi sempre la stessa nota si trova in un altro foro.",
3:"Esercizio di respirazione",
4:{q:"Che cosa fai quando resti senz'aria a metà frase?",o:["Soffiare più forte","Cercare un punto per cambiare direzione","Smettere di suonare","Suonare più veloce"],w:"Cambiare direzione è il modo di respirare dell'armonica."},
5:"Suona l'esercizio due minuti di seguito senza restare senza fiato."}},

"harmonica-7":{title:"Accordi e tremolo",goal:"Usare più fori insieme di proposito",b:{
0:"Finora abbiamo combattuto contro le note vicine. Ora le <b>usiamo di proposito</b>: più fori insieme danno un accordo pieno.",
1:"Soffiare nei fori 1–4 dà un accordo di do maggiore. Aspirare nei fori 1–4 dà un accordo di sol.",
2:"<b>Tremolo:</b> agita davanti alla bocca la mano che tiene l'armonica. Il suono ondeggia e ricorda un treno.",
3:"Accompagnamento di accordi",
4:{q:"Quale accordo esce soffiando nei fori dall'1 al 4?",o:["Sol maggiore","Do maggiore","La minore","Re maggiore"],w:"I soffi sono costruiti sulle note dell'accordo di do: do, mi e sol."},
5:"Suona un accompagnamento di accordi su una canzone che conosci, due minuti."}},

"harmonica-8":{title:"Una canzone intera",goal:"Suonare una melodia nota dall'inizio alla fine",b:{
0:"Ora si unisce tutto: foro singolo, ritmo e respirazione pianificata.",
2:"Melodia completa",
3:"Segnati in anticipo dove soffi e dove aspiri. Pianificare evita di restare senza fiato.",
4:{q:"Che cosa aiuta a non restare senza fiato?",o:["Suonare piano","Pianificare in anticipo soffi e aspirazioni","Suonare veloce","Accorciare la canzone"],w:"Pianificare la direzione dell'aria è l'abilità centrale dell'armonica."},
5:"Suona la melodia cinque volte di fila senza fermarti."}},

"harmonica-9":{title:"Bilancio e prossimi passi",goal:"Sapere che cosa hai imparato e dove andare",b:{
0:"Hai completato le basi: soffio e aspirazione, foro singolo, estensione completa, ritmo, accordi e una canzone intera.",
1:"Che cosa viene dopo: il <b>bending</b>, cambiare l'altezza del suono con la lingua, che permette di suonare le note assenti dall'accordatura. È questo a dare all'armonica il suo colore blues.",
2:"Brano finale",
3:"Il bending richiede mesi, non giorni. Non esercitarti prima che le note singole siano perfettamente pulite.",
4:{q:"Che cosa rende possibile il bending?",o:["Un'altra armonica","Cambiare la forma di bocca e lingua","Soffiare forte","Sostituire le ance"],w:"La forma della cavità orale modifica l'altezza del suono."},
5:"Suona il brano finale e registrati."}},

"glock-1":{title:"Il primo colpo",goal:"Produrre un suono pulito e capire la disposizione",b:{
0:"Il glockenspiel è lo strumento melodico più facile con cui cominciare: <b>niente da accordare, nessuna diteggiatura e nessun fiato</b>. Colpisci ed esce la nota giusta.",
1:"Le lame sono disposte esattamente come i tasti del pianoforte: una lunga fila di bianche e, sopra, gruppi di due e di tre.",
2:"Colpisci la lama segnata: questo è do",
3:["Tieni la bacchetta morbida, fra pollice e indice.","Colpisci il centro della lama, non l'estremità.","Solleva la bacchetta subito dopo il colpo. Una bacchetta che resta appoggiata soffoca il suono.","Basta un colpo leggero. Lo strumento fa il lavoro."],
4:"Suono spento? La bacchetta resta sulla lama. Pensa a rimbalzare, non a premere.",
5:{q:"Dove si colpisce la lama?",o:["All'estremità","Al centro","Vicino alla vite","È indifferente"],w:"Il centro dà il suono più pieno. Le estremità suonano spente."},
6:"Colpisci ogni lama bianca una volta, dal grave all'acuto, con suono pulito."}},

"glock-2":{title:"La scala e la tua prima melodia",goal:"Suonare una melodia conosciuta",b:{
0:"La scala di do maggiore sono semplicemente tutte le lame bianche di seguito. Per la prima melodia basta questo.",
1:"Scala di do maggiore",
2:"Prima melodia",
3:"<b>Alternare le mani:</b> destra-sinistra-destra-sinistra. Raddoppia la velocità senza sforzo aggiuntivo.",
4:{q:"Qual è il vantaggio di alternare le mani?",o:["Un suono più forte","Si suona più veloce senza sforzo","Le lame si consumano meno","Non c'è vantaggio"],w:"Una mano sola deve tornare indietro; due mani si alternano senza interruzione."},
5:"Suona la melodia alternando le mani, cinque volte."}},

"glock-3":{title:"Ritmo e dinamica",goal:"Suonare a intensità diverse e a tempo",b:{
0:"Sul glockenspiel il suono è breve, quindi <b>il tempo e l'intensità</b> sono tutta l'espressione a disposizione. È questo a trasformare un'esecuzione banale in una memorabile.",
1:"Ritmo di base",
2:"Prova a suonare la stessa melodia una volta forte e una volta delicatamente. La differenza è più grande di quanto sembri.",
3:"La stessa melodia, un altro ritmo",
4:{q:"Che cosa crea espressione sul glockenspiel?",o:["La durata delle note","L'intensità e il tempo","L'accordatura delle lame","Il numero di bacchette"],w:"Il suono è breve e fisso: i tuoi strumenti sono il volume e la precisione ritmica."},
5:"Suona la melodia tre volte: piano, medio e forte."}},

"glock-4":{title:"Due mani e salti",goal:"Suonare un passaggio che si sposta fra le zone",b:{
0:"Sul glockenspiel la mano non resta ferma. <b>L'occhio guida, la mano segue</b>, e questo si impara a parte.",
1:"Tre punti di riferimento: do, sol e do acuto",
2:["Individua i tre punti di riferimento sullo strumento.","Colpisci do e poi sol, senza guardare la bacchetta.","Aggiungi il do acuto.","Ora suona tutti e tre di seguito con metronomo a 60."],
3:"Guarda la lama <b>successiva</b> mentre colpisci quella attuale. È il segreto di ogni percussionista a tastiera.",
4:{q:"Dove si guarda mentre si suona?",o:["La bacchetta","La lama successiva","Solo lo spartito","È indifferente"],w:"Lo sguardo precede la mano, esattamente come nella lettura."},
5:"Suona do-sol-do venti volte senza sbagliare."}},

"glock-5":{title:"Le lame superiori",goal:"Suonare in una scala con il diesis",b:{
0:"Le lame superiori sono i semitoni, esattamente come i tasti neri del pianoforte, e negli stessi gruppi di due e di tre.",
1:"Scala di sol maggiore: attenzione al fa diesis",
2:"Le lame superiori sono più strette. Mira al centro, altrimenti la bacchetta scivola.",
3:{q:"Come sono disposte le lame superiori?",o:["In una fila uniforme","In gruppi di due e di tre","A caso","Non ci sono lame superiori"],w:"Esattamente come i tasti neri di un pianoforte."},
4:"Suona la scala di sol maggiore nei due sensi, cinque volte."}},

"glock-6":{title:"Ritmo più complesso",goal:"Suonare crome e note puntate",b:{
0:"Il suono del glockenspiel è breve, quindi <b>la precisione ritmica</b> si sente subito. Qui impari a dividere la pulsazione.",
1:"Crome",
2:"Melodia in crome",
3:"Conta ad alta voce: «uno-e-due-e». Contare ad alta voce è più preciso che contare a mente.",
4:{q:"Che cosa aiuta la precisione ritmica?",o:["Suonare forte","Contare ad alta voce","Suonare veloce","Guardarsi le mani"],w:"Contare ad alta voce collega il corpo al tempo."},
5:"Suona la melodia con metronomo a 70 e poi a 85."}},

"glock-7":{title:"Due voci",goal:"Suonare melodia e accompagnamento insieme",b:{
0:"Due mani significano due voci. Una mano suona la melodia, l'altra aggiunge una nota di appoggio.",
1:"Accordo di do: le tre note insieme",
2:"Melodia con appoggio",
3:"Comincia con la seconda mano che colpisce solo sul primo movimento di ogni battuta. Basta già a farla suonare piena.",
4:{q:"Qual è il modo più semplice per aggiungere una seconda voce?",o:["Suonare tutto due volte","Una nota di appoggio sul primo movimento","Suonare più veloce","Aggiungere una terza bacchetta"],w:"Un solo appoggio per battuta crea già la sensazione di accompagnamento."},
5:"Suona la melodia con l'appoggio, cinque volte."}},

"glock-8":{title:"Un brano da eseguire",goal:"Suonare un brano completo con sicurezza",b:{
0:"Ora si combina tutto: salti, lame superiori, ritmo e due voci.",
1:"Brano da eseguire",
2:"Studia il brano in tre sezioni separate e uniscile solo dopo. È così che studiano i professionisti.",
3:{q:"Come si impara un brano lungo?",o:["Suonandolo all'infinito","Dividendolo in sezioni e poi unendole","Suonando solo l'inizio","Accelerando gradualmente"],w:"Dividere fa risparmiare tempo e impedisce che gli errori si fissino."},
4:"Suona il brano tre volte di seguito senza fermarti."}},

"glock-9":{title:"Bilancio e prossimi passi",goal:"Sapere che cosa hai imparato e dove andare",b:{
0:"Hai completato: il colpo pulito, la scala, i salti, le lame superiori, il ritmo e le due voci.",
1:"Che cosa viene dopo: lo <b>xilofono e la marimba</b> (lame di legno, suono più caldo), <b>quattro bacchette</b> in due mani e la <b>lettura</b> mentre si suona.",
2:"Brano finale",
3:"Il glockenspiel è un'ottima porta d'ingresso a tutte le percussioni melodiche. L'abilità si trasferisce quasi per intero.",
4:{q:"Qual è la differenza fra glockenspiel e xilofono?",o:["La dimensione","Lame di metallo contro lame di legno","Il numero di lame","L'accordatura"],w:"Il metallo dà un suono brillante e lungo; il legno caldo e breve."},
5:"Suona il brano finale e registrati."}},

"mandolin-1":{title:"Primo contatto e corde vuote",goal:"Produrre un suono pulito e conoscere l'accordatura",b:{
0:"Il mandolino è accordato <b>esattamente come un violino</b> — sol, re, la, mi — ma ha i tasti. Ogni nota ha un posto fisso e non c'è nulla da cercare a orecchio.",
2:["Tieni il plettro fra pollice e indice, solo per la punta.","Suona alternando in giù e in su: è il movimento di base.","Mano sinistra: premi subito dietro il tasto, non sopra.","Suona ogni coppia di corde vuote quattro volte."],
3:"Ogni nota ha due corde affiancate. È questo a dare al mandolino il suo suono squillante.",
4:{q:"In che cosa il mandolino differisce dal violino?",o:["Nell'accordatura","Nell'avere i tasti","Nel numero di corde","Solo nelle dimensioni"],w:"L'accordatura è identica; la differenza sono i tasti, e sono proprio loro a facilitare l'inizio."},
5:"Suona ogni corda vuota otto volte, in giù e in su."}},

"mandolin-2":{title:"Prime note sul manico",goal:"Suonare la tua prima scala",b:{
0:"Grazie ai tasti, trovare una nota sul mandolino è questione di contare, non di ascoltare.",
2:"Cinque note",
3:"Un dito per tasto: è la regola che ti risparmia anni di correzioni.",
4:{q:"Come si trova una nota sul mandolino?",o:["Solo a orecchio","Dal numero del tasto","Dal colore della corda","Non se ne può essere certi"],w:"I tasti fissano l'altezza con precisione."},
5:"Suona le cinque note nei due sensi, dieci volte."}},

"mandolin-3":{title:"Una prima melodia",goal:"Suonare un brano intero",b:{
0:"Ora si unisce tutto: corde vuote, note sul manico e plettro regolare.",
2:"Melodia per mandolino",
3:"<b>Tremolo:</b> ripetizione rapida del plettro sulla stessa nota. È il suono che tutti riconoscono come mandolino, ma solo dopo che il plettro normale è stabile.",
4:{q:"Che cos'è il tremolo?",o:["Un cambio rapido di accordi","Ripetizione rapida del plettro sulla stessa nota","Suonare su due corde","Rallentare alla fine"],w:"È la tecnica distintiva del mandolino."},
5:"Suona la melodia cinque volte con plettro regolare."}},

"mandolin-4":{title:"Il tuo primo accordo",goal:"Suonare un accordo di sol e passarci sopra",b:{
0:"Sul mandolino un accordo sono <b>solo due dita</b> nella maggior parte dei casi, molte meno di quante ne richieda una chitarra.",
2:["Dito 1 sulla corda la, tasto 2.","Dito 2 sulla corda mi, tasto 3.","Le altre due corde restano vuote.","Suona in giù su tutte e quattro le coppie."],
3:"Premi subito dietro il tasto, non sopra. Lì serve meno forza.",
4:{q:"Quante dita servono per un accordo base sul mandolino?",o:["Quattro","Due","Tre","Nessuna"],w:"Due bastano per la maggior parte degli accordi aperti."},
5:"Alterna fra l'accordo di sol e le corde vuote, venti volte."}},

"mandolin-5":{title:"Due accordi e una canzone",goal:"Accompagnare una canzone intera con due accordi",b:{
0:"Con due accordi si accompagnano già centinaia di canzoni. Il passaggio fra loro è tutto l'esercizio.",
1:"Plettrata in giù e in su",
2:"<b>La regola del cambio:</b> solleva le dita un attimo prima del movimento, non sopra di esso. Così non resta un buco nel ritmo.",
3:"Esercizio di accompagnamento",
4:{q:"Quando si sollevano le dita nel cambio di accordo?",o:["Esattamente sul movimento","Un attimo prima del movimento","Dopo il movimento","È indifferente"],w:"Sollevarle prima mantiene la continuità del ritmo."},
5:"Alterna i due accordi per due minuti senza fermarti."}},

"mandolin-6":{title:"Il tremolo",goal:"Produrre un suono tenuto con plettrata ripetuta",b:{
0:"Il mandolino non ha suono lungo: si spegne subito. Il <b>tremolo</b> è la soluzione: una ripetizione rapida che crea l'illusione di un suono tenuto.",
1:["Tieni il plettro molto morbido: è questa la chiave.","Muoviti dal polso, non dal gomito.","Comincia lento e regolare, e solo dopo accelera.","Suona una nota in tremolo per quattro secondi."],
2:"Una presa rigida dà un tremolo a scatti. Più la presa è morbida, più il suono è liscio.",
3:"Nota lunga in tremolo",
4:{q:"Che cosa conta di più nel tremolo?",o:["La velocità","Una presa rilassata","Molta pressione","Un plettro spesso"],w:"Il rilassamento permette la velocità; la tensione la impedisce."},
5:"Esercita il tremolo su una sola nota, un minuto per corda."}},

"mandolin-7":{title:"Scale su due ottave",goal:"Estendere l'estensione lungo il manico",b:{
0:"Grazie all'accordatura per quinte, lo stesso schema di dita si ripete su ogni coppia di corde. Si impara una volta e si suona ovunque.",
2:"Scala di sol su due ottave",
3:"Lo schema imparato sulla corda sol funziona esattamente allo stesso modo sulla corda re. È questo il grande risparmio dell'accordatura per quinte.",
4:{q:"Qual è il vantaggio dell'accordatura per quinte?",o:["Un suono più forte","Lo stesso schema si ripete su ogni coppia di corde","È più facile da accordare","Meno corde"],w:"Lo schema si conserva, quindi va imparato una sola volta."},
5:"Suona la scala su due ottave, dieci volte."}},

"mandolin-8":{title:"Melodia con accompagnamento",goal:"Suonare una canzone intera e inserire gli accordi",b:{
0:"Ora si combina: melodia, accordi e tremolo nello stesso brano.",
1:"Brano combinato",
2:"Suona prima solo la melodia, poi solo gli accordi, e unisci soltanto dopo. Unire troppo presto rovina entrambi.",
3:{q:"Come si uniscono melodia e accompagnamento?",o:["Suonandoli insieme fin dall'inizio","Imparando ciascuno a parte e poi unendoli","Rinunciando a uno dei due","Suonando molto lentamente"],w:"Prima separare, poi unire: è la via rapida."},
4:"Suona il brano combinato cinque volte."}},

"mandolin-9":{title:"Bilancio e prossimi passi",goal:"Sapere che cosa hai imparato e dove andare",b:{
0:"Hai completato: corde vuote, note sul manico, accordi, tremolo e scale su due ottave.",
1:"Che cosa viene dopo: lo <b>stile bluegrass</b> (plettrata rapida e precisa), gli <b>accordi chiusi</b> che si spostano lungo il manico e l'<b>improvvisazione</b> sulle scale imparate.",
2:"Brano finale",
3:"Il mandolino condivide l'accordatura con il violino: tutto ciò che hai imparato qui si trasferisce quasi per intero, se vorrai provarlo.",
4:{q:"Quale strumento condivide l'accordatura del mandolino?",o:["La chitarra","Il violino","Il basso","L'ukulele"],w:"Entrambi sono accordati sol-re-la-mi."},
5:"Suona il brano finale e registrati."}}

});
